 ops=[job('credit','credit','Correct actual credit source|改实际署名源'),job('clip','clip','Render corrected clip|导出修正剪辑','credit'),job('replace','held_clip','Replace actual held clip|替换实际持有剪辑','clip'),job('script','script','Generate final accessible script|生成最终无障碍台本','credit'),job('interpret','segment','Deliver script and ingest returned segment|交台本并并入返回手语段','script',accepted=['interpreter']),job('replay','replay','Render full accessible replay|导完整无障碍回放','held_clip','segment'),job('slot','slot','Reserve accepted make-up slot|订已同意补练位',accepted=['complainant','coach']),job('pass','pass','Issue actual make-up artifact|签实际补练凭据','slot'),job('attach','player','Replace actual replay player attachment|替换实际回放播放器附件','replay'),job('paid-link','paid_link','Issue actual paid replay entitlement|签实际已付回放权益','player')]
 keys=[['clip','owner','public_credit'],['clip'],['player','clip'],['script','credit_owner'],['script'],['replay','duration_seconds'],['account','day','time'],['token','account','slot'],['player','replay'],['token','account','replay']]
 for o,k in zip(ops,keys):o['keys']=k
 v={'credit':f'C7/{owner}/Rem','clip':'C7-corrected','held_clip':'P7/C7-corrected','script':f'S4/{owner}','segment':'S4','replay':'R4/600','slot':'Rem17/Wednesday/18:00','pass':'M17/Rem17/Wednesday18:00','player':'P7/R4','paid_link':'L17/Rem17/R4'}
